import { useCallback, useMemo, useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
};

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() + days);
  return date;
};

const isSameDay = (a: Date | null | undefined, b: Date) =>
  !!a &&
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internal, setInternal] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internal;

  const presets = useMemo(
    () => [
      { id: 'today', label: 'Сегодня', date: shiftDays(0) },
      { id: 'yesterday', label: 'Вчера', date: shiftDays(-1) },
      { id: 'week-ago', label: 'Неделя назад', date: shiftDays(-7) },
    ],
    [],
  );

  const commit = useCallback(
    (next: Date | null) => {
      if (value === undefined) setInternal(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {presets.map((preset) => {
          const active = isSameDay(selected, preset.date);
          return (
            <JxChip
              key={preset.id}
              active={active}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => commit(preset.date)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  commit(preset.date);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale={locale} value={selected} onValueChange={commit} />

      <p
        aria-live="polite"
        style={{ margin: 0, fontSize: '14px', color: 'var(--jx-text-2)' }}
      >
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString(locale, {
              day: 'numeric',
              month: 'long',
              year: 'numeric',
            })}`
          : 'Выберите дату отчёта на календаре или одним из вариантов выше.'}
      </p>
    </div>
  );
}

